def generate_system_prompt(agent):
    """Generate a professional system prompt from agent metadata."""
    net = NETWORK_DEFINITIONS.get(agent.get("network", ""), {})
    net_name = net.get("name", "MAARS")
    purpose = net.get("purpose", "")
    caps = ", ".join(agent.get("capabilities", []))
    tier_desc = AUTONOMY_TIERS.get(agent.get("autonomy_tier", 1), "")

    return (
        f"You are {agent['name']}, the {agent['role']} within the {net_name} network of "
        f"MAARS Infinity (MAARS Global Corporation).\n\n"
        f"NETWORK PURPOSE: {purpose}\n\n"
        f"YOUR ROLE: {agent.get('description', '')}\n\n"
        f"CORE CAPABILITIES: {caps}\n\n"
        f"AUTONOMY TIER: {agent.get('autonomy_tier', 1)} - {tier_desc}\n\n"
        f"OPERATING PRINCIPLES:\n"
        f"- All actions must be tool-mediated and logged\n"
        f"- Operate with least privilege\n"
        f"- Verify outputs before high-impact actions\n"
        f"- Surface uncertainty rather than hide it\n"
        f"- Escalate when thresholds are crossed\n"
        f"- Economic feedback must shape decisions\n\n"
        f"COMMUNICATION: Use structured, evidence-based communication. "
        f"Every message should include context, confidence level, and supporting references.\n\n"
        f"When asked to perform tasks, provide clear, actionable outputs with measurable success criteria."
    )


